#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""把 docx 顺序导出为 Markdown（段落+标题+表格），保持文档原有顺序。"""
import sys
from docx import Document
from docx.oxml.ns import qn
from docx.text.paragraph import Paragraph
from docx.table import Table

PATH = '/home/mi/vela_competition_continue/VelaSight_功能展示报告.docx'
OUT = '/home/mi/convwork/extracted.md'

doc = Document(PATH)


def iter_block_items(parent):
    parent_elm = parent.element.body
    for child in parent_elm.iterchildren():
        if child.tag == qn('w:p'):
            yield Paragraph(child, parent)
        elif child.tag == qn('w:tbl'):
            yield Table(child, parent)


def para_to_md(p):
    text = p.text.strip()
    if not text:
        return ''
    style = p.style.name if p.style else ''
    if style.startswith('Heading 1') or style == 'Title':
        return '# ' + text
    if style.startswith('Heading 2'):
        return '## ' + text
    if style.startswith('Heading 3'):
        return '### ' + text
    if style == 'List Number':
        return '1. ' + text
    if style == 'List Bullet':
        return '- ' + text
    # detect callout-like shading (yellow background) -> blockquote
    shd = p._p.find(qn('w:pPr') + '/' + qn('w:shd')) if p._p.find(qn('w:pPr')) is not None else None
    is_shaded = False
    pPr = p._p.pPr
    if pPr is not None:
        shd = pPr.find(qn('w:shd'))
        if shd is not None:
            fill = shd.get(qn('w:fill'))
            if fill and fill.upper() != 'FFFFFF' and fill.upper() != 'AUTO':
                is_shaded = True
    if is_shaded:
        return '> ' + text
    return text


def table_to_md(t):
    rows = []
    for row in t.rows:
        cells = [c.text.strip().replace('\n', ' ') for c in row.cells]
        rows.append(cells)
    if not rows:
        return ''
    lines = []
    header = rows[0]
    lines.append('| ' + ' | '.join(header) + ' |')
    lines.append('| ' + ' | '.join(['---'] * len(header)) + ' |')
    for r in rows[1:]:
        lines.append('| ' + ' | '.join(r) + ' |')
    return '\n'.join(lines)


out_lines = []
for block in iter_block_items(doc):
    if isinstance(block, Paragraph):
        md = para_to_md(block)
        if md:
            out_lines.append(md)
            out_lines.append('')
    elif isinstance(block, Table):
        out_lines.append(table_to_md(block))
        out_lines.append('')

with open(OUT, 'w', encoding='utf-8') as f:
    f.write('\n'.join(out_lines))

print('wrote', OUT, 'lines:', len(out_lines))

